/**
 * Check if a given object implements the EdgarFilingFile interface.
 */
export function instanceOfEdgarFilingFile(value) {
    if (!("name" in value) || value["name"] === undefined)
        return false;
    if (!("type" in value) || value["type"] === undefined)
        return false;
    if (!("url" in value) || value["url"] === undefined)
        return false;
    return true;
}
export function EdgarFilingFileFromJSON(json) {
    return EdgarFilingFileFromJSONTyped(json, false);
}
export function EdgarFilingFileFromJSONTyped(json, ignoreDiscriminator) {
    if (json == null) {
        return json;
    }
    return {
        name: json["name"],
        size: json["size"] == null ? undefined : json["size"],
        type: json["type"],
        url: json["url"],
    };
}
export function EdgarFilingFileToJSON(json) {
    return EdgarFilingFileToJSONTyped(json, false);
}
export function EdgarFilingFileToJSONTyped(value, ignoreDiscriminator = false) {
    if (value == null) {
        return value;
    }
    return {
        name: value["name"],
        size: value["size"],
        type: value["type"],
        url: value["url"],
    };
}
